// Renders the `context.md` snapshot fetch writes (design doc §5.3). Comments newest first
// (default max 20, each capped at 2000 chars); related items are depth 1 only; the header
// records fetch time next to the story's changedAt so a later fetch can detect drift.
import { renderTable, truncate, utcTimestamp } from './output.mjs';

const COMMENT_CAP = 2000;
const RELATED_EXCERPT_CAP = 500;
const CLONE_HINT_RE = /clon|duplicat/i;

/** Cheap heuristic for the Note column on `related` links — a hint for the model, never a
 * hard rule (§5.3: "Note column heuristics are hints, the model decides relevance"). */
function relationNote(relation) {
  if (relation.kind !== 'related') return '';
  if (relation.comment && CLONE_HINT_RE.test(relation.comment)) {
    return 'possible clone leftover: linked at creation, generic link comment';
  }
  return '';
}

function headerLine({ id, generatedAt, changedAt }) {
  const changedSuffix = changedAt ? ` (story changed ${changedAt})` : '';
  return `<!-- generated by tracker.mjs fetch ${id} at ${generatedAt}${changedSuffix} - do not edit -->`;
}

/** Renders the full context.md content for one fetch. `related` is an array of
 * WorkItemSummary-shaped objects already annotated with `kind` (the relation type) —
 * depth-1 only, no recursion. */
export function renderContextMd({ id, workItem, comments = [], related = [], generatedAt = utcTimestamp(), maxComments = 20 }) {
  const lines = [];
  lines.push(headerLine({ id, generatedAt, changedAt: workItem.changedAt }));
  lines.push(`# ${id} — ${workItem.type}: ${workItem.title}`);

  const metaParts = [`State: ${workItem.state}`];
  if (workItem.iterationPath) metaParts.push(`Iteration: ${workItem.iterationPath}`);
  if (workItem.areaPath) metaParts.push(`Area: ${workItem.areaPath}`);
  if (workItem.tags?.length) metaParts.push(`Tags: ${workItem.tags.join(', ')}`);
  lines.push(metaParts.join(' | '));
  lines.push(`URL: ${workItem.url}`);
  lines.push('');

  lines.push('## Description');
  lines.push(workItem.description || '_(none)_');
  lines.push('');

  lines.push('## Acceptance Criteria');
  lines.push(workItem.acceptanceCriteria || '_(none)_');
  lines.push('');

  if (related.length) {
    lines.push('## Related work items');
    lines.push(
      renderTable(
        ['Relation', 'ID', 'Type', 'State', 'Title', 'Note'],
        related.map((item) => [item.kind, item.id, item.type, item.state, item.title, relationNote(item)])
      )
    );
    lines.push('');
    for (const item of related) {
      lines.push(`### ${item.id} — ${item.title} (${item.kind})`);
      lines.push(truncate(item.descriptionExcerpt ?? '', RELATED_EXCERPT_CAP) || '_(no description)_');
      lines.push('');
    }
  }

  const shown = comments.slice(0, maxComments);
  lines.push(`## Comments (newest first, ${shown.length} of ${comments.length})`);
  if (shown.length === 0) {
    lines.push('_(none)_');
  } else {
    for (const comment of shown) {
      lines.push(`- **${comment.createdAt}, ${comment.author}**: ${truncate(comment.markdown, COMMENT_CAP)}`);
    }
  }

  return `${lines.join('\n').trimEnd()}\n`;
}

/** Extracts the `changedAt` recorded in a previously-written context.md's header comment,
 * or null if the file has no header (unexpected content, or first fetch). */
export function extractPreviousChangedAt(existingContent) {
  const match = existingContent?.match(/^<!-- generated by tracker\.mjs fetch \d+ at [^(]+\(story changed ([^)]+)\) - do not edit -->/);
  return match ? match[1].trim() : null;
}

/** True when a re-fetch's changedAt differs from what the last context.md recorded — the
 * "story changed since last fetch" notice (§5.3 rule 4). */
export function storyChangedSinceLastFetch(existingContent, newChangedAt) {
  const previous = extractPreviousChangedAt(existingContent);
  return Boolean(previous && newChangedAt && previous !== newChangedAt);
}
